package com.andye.warmod.radar.client.gui;
import com.andye.warmod.icbm.IcbmTrajectory;import com.andye.warmod.radar.*;import com.andye.warmod.radar.client.*;import com.andye.warmod.warhead.*;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.world.phys.Vec3;
public final class RadarTrackRenderer{private RadarTrackRenderer(){}public static void render(GuiGraphicsExtractor g,ClientRadarTrack track,RadarMapTransform t,double now,int left,int top,int width,int height,boolean selected){int color=track.snapshot().payloadType()==WarheadPayloadType.NUCLEAR?0xffff5a32:0xffffad32;Vec3 launch=track.launch(),target=track.target();point(g,t,launch,left,top,width,height,0xff66d9ff,2);cross(g,t,target,left,top,width,height,color);drawRoute(g,track,t,left,top,width,height,color);Vec3 p=track.position(now);int x=(int)Math.round(t.screenX(p.x,left,width)),y=(int)Math.round(t.screenY(p.z,top,height));if(x<left||x>=left+width||y<top||y>=top+height){x=Math.max(left+3,Math.min(left+width-4,x));y=Math.max(top+3,Math.min(top+height-4,y));g.fill(x-3,y-3,x+4,y+4,color);}else{int r=selected?4:3;g.fill(x-r,y-r,x+r+1,y+r+1,color);if(selected){g.fill(x-r-1,y-r-1,x+r+2,y-r,0xffffffff);g.fill(x-r-1,y+r+1,x+r+2,y+r+2,0xffffffff);}}}private static void drawRoute(GuiGraphicsExtractor g,ClientRadarTrack track,RadarMapTransform t,int l,int top,int w,int h,int color){RadarTrackSnapshot s=track.snapshot();if(s.carrierPlan().isPresent()){RadarCarrierPlanSnapshot p=s.carrierPlan().get();com.andye.warmod.icbm.IcbmFlightPlan plan=new com.andye.warmod.icbm.IcbmFlightPlan(s.trackId(),s.ownerPlayerId(),p.launchPosition(),p.burnoutPosition(),p.separationPosition(),p.intendedTarget(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.coastTicks(),p.visualSeed(),s.payloadType());for(int i=0;i<=80;i++)point(g,t,IcbmTrajectory.position(plan,plan.separationTick()*i/80.0),l,top,w,h,(color&0x00ffffff)|0x66000000,1);}if(s.terminalPlan().isPresent()){RadarTerminalPlanSnapshot p=s.terminalPlan().get();for(int i=0;i<=36;i++)point(g,t,WarheadTrajectory.position(p.startPosition(),p.targetPosition(),p.flightTicks()*i/36.0,p.flightTicks()),l,top,w,h,(color&0x00ffffff)|0x88000000,1);}}private static void point(GuiGraphicsExtractor g,RadarMapTransform t,Vec3 p,int l,int top,int w,int h,int c,int r){int x=(int)t.screenX(p.x,l,w),y=(int)t.screenY(p.z,top,h);if(x>=l&&x<l+w&&y>=top&&y<top+h)g.fill(x-r,y-r,x+r+1,y+r+1,c);}private static void cross(GuiGraphicsExtractor g,RadarMapTransform t,Vec3 p,int l,int top,int w,int h,int c){int x=(int)t.screenX(p.x,l,w),y=(int)t.screenY(p.z,top,h);if(x>=l+4&&x<l+w-4&&y>=top+4&&y<top+h-4){g.fill(x-5,y,x+6,y+1,c);g.fill(x,y-5,x+1,y+6,c);}}}
